@tailwind base;
@tailwind components;
@tailwind utilities;

html,
body,
#root {
  height: 100%;
}

body {
  margin: 0;
  background: #09090b;
  color: #f4f4f5;
  font-family: ui-sans-serif, system-ui, -apple-system, 'Segoe UI', sans-serif;
  overflow: hidden;
  user-select: none;
}

input,
textarea,
pre,
code,
.selectable {
  user-select: text;
}

::-webkit-scrollbar {
  width: 5px;
  height: 5px;
}

::-webkit-scrollbar-track {
  background: #18181b;
}

::-webkit-scrollbar-thumb {
  background: #3f3f46;
  border-radius: 2px;
}

::-webkit-scrollbar-thumb:hover {
  background: #52525b;
}

* {
  scrollbar-width: thin;
  scrollbar-color: #3f3f46 #18181b;
}

@layer components {
  .btn {
    @apply inline-flex h-8 items-center justify-center gap-1 rounded px-2.5 font-mono text-[11px] font-medium transition-colors focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-zinc-500 disabled:pointer-events-none disabled:opacity-40;
  }
  .btn-primary {
    @apply btn bg-zinc-100 text-zinc-900 hover:bg-white;
  }
  .btn-ghost {
    @apply btn border border-border bg-transparent text-zinc-300 hover:border-zinc-600 hover:bg-zinc-800/60 hover:text-zinc-100;
  }
  .btn-danger {
    @apply btn border border-red-900/80 bg-red-950 text-red-300 hover:bg-red-900/80;
  }
  .btn-icon {
    @apply inline-flex h-8 w-8 items-center justify-center rounded border border-border text-zinc-400 transition-colors hover:border-zinc-600 hover:bg-zinc-800/60 hover:text-zinc-100 focus-visible:outline-none focus-visible:ring-1 focus-visible:ring-zinc-500;
  }
  .field {
    @apply w-full rounded border border-border bg-background px-2 py-1.5 font-mono text-xs text-zinc-100 outline-none transition-colors placeholder:text-muted focus:border-zinc-600 focus-visible:ring-1 focus-visible:ring-zinc-600/50;
  }
  .chip {
